SELECT id, product_name, category, brand, price, cost, stock_qty, launch_date, tags, supplier_id, AVG(stock_qty) OVER (PARTITION BY category, supplier_id ORDER BY launch_date, id ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING) AS stock_qty_avg_6_prior, SUM(cost) OVER (PARTITION BY supplier_id ORDER BY price, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_cost, NTILE(4) OVER (PARTITION BY supplier_id, category ORDER BY price, id) AS price_bucket FROM products;
